for p in range(N):
    x = 0
    for j, qubit in enumerate(order):
        if (p >> qubit) & 1:
            x |= 1 << j

    for r in range(N):
        y = 0
        for j, qubit in enumerate(order):
            if (r >> qubit) & 1:
                y |= 1 << j

        U[r, p] = np.exp(2j * np.pi * x * y / N) / np.sqrt(N)

qc = QuantumCircuit(4)
qc.append(UnitaryGate(U), [0, 1, 2, 3])

